arguments.old_str:
using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

// Note-taking state shared across tool invocations
var notes = new List<string>();

// Define the tools available to the agent
var searchTool = AIFunctionFactory.Create(SearchWeb);
var noteTool = AIFunctionFactory.Create(TakeNote);
var readNotesTool = AIFunctionFactory.Create(ReadNotes);

// Build the chat client with OpenAI provider
IChatClient chatClient = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient("gpt-4o-mini-2024-07-18").AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// Create the agent using Microsoft Agent Framework
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. When given a topic:
        1. Search the web multiple times with different queries to gather diverse information.
        2. Take notes on the key findings from each search.
        3. After gathering enough information, read your notes and produce a concise summary.
        Always search at least 3 times with varied queries before summarizing.
        """,
};

// Get the research topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// Run the agent
var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        Tools = [searchTool, noteTool, readNotesTool],
    },
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();

// --- Tool definitions ---

[Description("Searches the web for information on a query. Returns a list of relevant results.")]
static string SearchWeb(
    [Description("The search query to look up")] string query)
{
    Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

    // Simulated search results for demonstration purposes.
    // Replace with a real search API (Bing, Google, etc.) for production use.
    return $"""
        Search results for "{query}":
        1. According to recent research, {query} is a rapidly evolving area with significant developments in 2025-2026.
        2. Experts note that {query} has seen a 40% increase in investment over the past year.
        3. Key challenges include scalability, ethical considerations, and integration with existing systems.
        4. Leading organizations in this space include major tech companies and specialized startups.
        5. Future outlook suggests continued growth with emphasis on responsible development.
        """;
}

[Description("Takes a note to remember important information found during research.")]
string TakeNote(
    [Description("The note content to save")] string note)
{
    notes.Add(note);
    Console.WriteLine($"  [Tool] Note saved ({notes.Count} total)");
    return $"Note saved successfully. You now have {notes.Count} note(s).";
}

[Description("Reads all notes taken so far during the research process.")]
string ReadNotes()
{
    if (notes.Count == 0)
        return "No notes have been taken yet.";

    Console.WriteLine($"  [Tool] Reading {notes.Count} note(s)");
    return string.Join("\n\n", notes.Select((n, i) => $"Note {i + 1}: {n}"));
}

